package local.proskurnin.remote;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
public class RemoteActivity extends Activity {
 final Handler h=new Handler();TextView state,address,code,phones,helper;ImageView qr;Button enable;String drawnUrl="",shownPending="";boolean visible;Bitmap image;
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 TextView label(LinearLayout root,String text,int size,int color){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,0,0,dp(8));root.addView(v);return v;}
 Button button(LinearLayout root,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextSize(15);b.setAllCaps(false);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(12),0,dp(12),0);b.setTextColor(0xffe4edf7);StateListDrawable bg=new StateListDrawable();for(boolean focus:new boolean[]{true,false}){GradientDrawable shape=new GradientDrawable();shape.setCornerRadius(dp(10));shape.setColor(focus?0xff344b65:0xff1d2a3b);if(focus)shape.setStroke(dp(1),0xffbdd8f5);bg.addState(focus?new int[]{android.R.attr.state_focused}:new int[]{},shape);}b.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(36));p.bottomMargin=dp(7);root.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setBackgroundDrawable(new ColorDrawable(0xff0d1420));getWindow().getDecorView().setSystemUiVisibility(5894);LinearLayout root=new LinearLayout(this);root.setPadding(dp(34),dp(24),dp(34),dp(20));root.setBackgroundColor(0xff0d1420);setContentView(root);LinearLayout left=new LinearLayout(this);left.setOrientation(1);root.addView(left,new LinearLayout.LayoutParams(0,-1,1));LinearLayout right=new LinearLayout(this);right.setOrientation(1);right.setGravity(Gravity.CENTER);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(dp(300),-1);rp.leftMargin=dp(35);root.addView(right,rp);
  label(left,"Пульт с телефона",29,Color.WHITE);state=label(left,"",16,0xffa9cdb9);address=label(left,"",20,0xffd7e6f5);helper=label(left,"",13,0xff9aabc0);
  enable=button(left,"",()->{boolean on=!getSharedPreferences("remote",0).getBoolean("enabled",false);getSharedPreferences("remote",0).edit().putBoolean("enabled",on).apply();if(on)startForegroundService(new Intent(this,RemoteService.class));else stopService(new Intent(this,RemoteService.class));refresh();});
  button(left,"Подключить телефон · новый код",()->{RemoteService s=RemoteService.instance;if(s==null||s.server==null){Toast.makeText(this,"Сначала включите сервер в домашней сети",0).show();return;}s.auth.open();shownPending="";refresh();});
  button(left,"Ввод текста с телефона",()->new AlertDialog.Builder(this).setTitle("Активное поле ТВ").setMessage("Доступны обычные текстовые поля. Пароли не читаются и не передаются. Служба работает только при включённом пульте.").setPositiveButton("Вкл / выкл",(d,n)->{boolean on=!getSharedPreferences("remote",0).getBoolean("text_input",true);getSharedPreferences("remote",0).edit().putBoolean("text_input",on).apply();Toast.makeText(this,on?"Ввод включён":"Ввод выключен",0).show();}).setNeutralButton("Доступность",(d,n)->startActivity(new Intent("android.settings.ACCESSIBILITY_SETTINGS"))).setNegativeButton("Закрыть",null).show());
  button(left,"Быстрые приложения",()->chooseApps());
  button(left,"Забыть все телефоны",()->new AlertDialog.Builder(this).setMessage("Отозвать доступ у всех телефонов?").setPositiveButton("Забыть",(d,n)->{RemoteService s=RemoteService.instance;if(s!=null)s.auth.clear();else new RemoteAuth(this).clear();refresh();}).setNegativeButton("Отмена",null).show());
  button(left,"Назад",()->finish());phones=label(left,"",13,0xff93a5bb);label(left,"Телефон и ТВ — в одной домашней сети.\nБез облака и проброса портов. HTTP не шифрует команды: используйте доверенную сеть.\nВо сне ТВ сервер закрывается; разбудите телевизор физическим пультом.",12,0xff8294aa);
  qr=new ImageView(this);right.addView(qr,new LinearLayout.LayoutParams(dp(214),dp(214)));TextView hint=label(right,"Наведите камеру телефона\nи введите код с этого экрана",15,0xffb7c8da);hint.setGravity(Gravity.CENTER);code=label(right,"",38,Color.WHITE);code.setGravity(Gravity.CENTER);enable.requestFocus();if(getSharedPreferences("remote",0).getBoolean("enabled",false))startForegroundService(new Intent(this,RemoteService.class));
 }
 void chooseApps(){Map<String,String> installed=RemoteActions.apps(this);String[] packages=installed.keySet().toArray(new String[0]),names=installed.values().toArray(new String[0]);boolean[] selected=new boolean[packages.length];JSONArray current=RemoteActions.selected(this);for(int i=0;i<packages.length;i++)for(int j=0;j<current.length();j++)if(packages[i].equals(current.optString(j)))selected[i]=true;
  new AlertDialog.Builder(this).setTitle("Быстрые приложения · до 8").setMultiChoiceItems(names,selected,(d,n,on)->{int count=0;for(boolean s:selected)if(s)count++;if(on&&count>8){selected[n]=false;((AlertDialog)d).getListView().setItemChecked(n,false);Toast.makeText(this,"Можно выбрать до 8 приложений",0).show();}}).setPositiveButton("Сохранить",(d,n)->{JSONArray values=new JSONArray();for(int i=0;i<packages.length&&values.length()<8;i++)if(selected[i])values.put(packages[i]);getSharedPreferences("remote",0).edit().putString("apps",values.toString()).apply();}).setNegativeButton("Отмена",null).show();
 }
 final Runnable tick=new Runnable(){public void run(){if(!visible)return;refresh();h.postDelayed(this,1000);}};
 void set(TextView v,String value){if(!value.contentEquals(v.getText()))v.setText(value);}
 void refresh(){boolean enabled=getSharedPreferences("remote",0).getBoolean("enabled",false);RemoteService s=RemoteService.instance;set(enable,enabled?"Сервер: включён · выключить":"Сервер: выключен · включить");set(state,!enabled?"Сервер выключен":s==null?"Запускаю…":s.status);String url=s==null?"":s.url();set(address,url.isEmpty()?"Локальный адрес появится после включения":url);set(helper,s!=null&&s.bridgeReady?"Управление: ADB-помощник":TextInputService.available()?"Управление: доступность Android · зависит от приложения":"Управление: лаунчер и громкость · включите доступность для других приложений");set(phones,"Телефоны: "+(s==null?new RemoteAuth(this).names():s.auth.names()));
  if(!url.equals(drawnUrl)){drawnUrl=url;qr.setImageDrawable(null);if(image!=null){image.recycle();image=null;}if(!url.isEmpty())try{io.nayuki.qrcodegen.QrCode q=io.nayuki.qrcodegen.QrCode.encodeText(url,io.nayuki.qrcodegen.QrCode.Ecc.MEDIUM);int scale=8,size=(q.size+8)*scale;image=Bitmap.createBitmap(size,size,Bitmap.Config.RGB_565);image.eraseColor(Color.WHITE);Canvas canvas=new Canvas(image);Paint paint=new Paint();paint.setColor(Color.BLACK);for(int y=0;y<q.size;y++)for(int x=0;x<q.size;x++)if(q.getModule(x,y))canvas.drawRect((x+4)*scale,(y+4)*scale,(x+5)*scale,(y+5)*scale,paint);BitmapDrawable d=new BitmapDrawable(getResources(),image);d.setFilterBitmap(false);qr.setImageDrawable(d);}catch(Exception ignored){}}
  String pin=s==null?"":s.auth.visibleCode();set(code,pin.isEmpty()?"Код закрыт":pin.substring(0,3)+" "+pin.substring(3)+"\n"+(s.auth.seconds()/5*5)+" с");code.setTextSize(pin.isEmpty()?20:32);
  if(s!=null){RemoteAuth.Pending pending=s.auth.request();if(pending!=null&&!pending.approved&&!pending.rejected&&!pending.id.equals(shownPending)){shownPending=pending.id;final String id=pending.id;new AlertDialog.Builder(this).setTitle("Разрешить управление ТВ?").setMessage(pending.name+" · "+pending.ip+"\nТелефон сможет нажимать кнопки, открывать приложения и вводить текст в обычные активные поля (кроме паролей).").setPositiveButton("Разрешить",(d,n)->s.auth.approve(id,true)).setNegativeButton("Отклонить",(d,n)->s.auth.approve(id,false)).setOnCancelListener(d->s.auth.approve(id,false)).show();}}
 }
 protected void onResume(){super.onResume();visible=true;h.post(tick);}
 protected void onPause(){visible=false;h.removeCallbacks(tick);super.onPause();}
 protected void onDestroy(){h.removeCallbacksAndMessages(null);qr.setImageDrawable(null);if(image!=null)image.recycle();super.onDestroy();}
}
